// Arte das categorias no estilo do Calen: 161 ícones desenhados em três tons e a fórmula que
// os pinta (tema claro e escuro). Gerado de analysis/calen (app web do Calen); o uso é
// autorizado pelo usuário. Os tons-marcador no SVG são #0000A1 (base), #0000A2 (volume) e
// #0000A3 (detalhe). Sem imports: testável em Node.

// Cores de categoria do Calen, sem a família roxa (o roxo da marca vira o amarelo Solar).
export const CALEN_COLORS = {"green": "#2FB22F", "blue": "#3B82F6", "pink": "#EC4899", "orange": "#FFA63D", "red": "#E5484D", "teal": "#14B8A6", "yellow": "#FACC15", "amber": "#F59E0B", "indigo": "#6366F1", "cyan": "#06B6D4", "slate": "#64748B", "steel": "#7B93C0", "rose": "#F43F5E", "coral": "#FF7F50", "ocean": "#0284C7", "sky": "#0EA5E9", "emerald": "#10B981", "forest": "#15803D", "olive": "#7C8B2A", "gold": "#CA8A04", "tangerine": "#F97316", "brown": "#A0522D", "sand": "#C2A27A", "cherry": "#D6336C", "salmon": "#FA8072", "terracotta": "#C8553D", "copper": "#B87333", "lime": "#82B814", "mint": "#20B486", "petrol": "#0E7C86", "turquoise": "#12A4B6", "sapphire": "#3B5BDB", "chocolate": "#8B5A3C", "moss": "#5C7F3A", "gray": "#94A3B8"};

// Mistura `a` com `b` na proporção `t` (0 = só a, 1 = só b), em hexadecimal #RRGGBB.
export function mix(a, b, t) {
  const p = (h, i) => parseInt(h.slice(i, i + 2), 16);
  return "#" + [1, 3, 5].map((i) => Math.round(p(a, i) * (1 - t) + p(b, i) * t).toString(16).padStart(2, "0")).join("").toUpperCase();
}

// Tons do ícone. `box` é o fundo do bloco; `onSolid` pinta branco sobre o bloco colorido.
export function calenTones(color, dark = false, onSolid = false) {
  if (onSolid) return { box: color, base: "#FFFFFF", volume: mix(color, "#FFFFFF", 0.55), detail: mix(color, "#000000", 0.35) };
  const volume = mix(color, "#000000", 0.15);
  const detail = mix(color, "#000000", 0.5);
  return dark
    ? { box: mix(mix(color, "#808080", 0.35), "#141414", 0.72), base: mix(color, "#FFFFFF", 0.2), volume, detail }
    : { box: mix(color, "#FFFFFF", 0.84), base: color, volume, detail };
}

export const hasCalenIcon = (name) => Object.prototype.hasOwnProperty.call(CALEN_ICONS, name);
export const calenIconNames = () => Object.keys(CALEN_ICONS);

// SVG pronto (string) do ícone `name` na cor `color`.
export function calenSvg(name, color, dark = false, onSolid = false) {
  const t = calenTones(color, dark, onSolid);
  return CALEN_ICONS[hasCalenIcon(name) ? name : "other"].replace(/#0000A1/g, t.base).replace(/#0000A2/g, t.volume).replace(/#0000A3/g, t.detail);
}

